"""Evidence-led interpretation of the finite five-path matrix, no performance claims."""
from ir_common import *

def md(frame):
 def value(v):return f'{v:.10g}' if isinstance(v,(float,np.floating)) else str(v)
 return '| '+' | '.join(frame.columns)+' |\n| '+' | '.join(['---']*len(frame.columns))+' |\n'+'\n'.join('| '+' | '.join(value(v) for v in row)+' |' for row in frame.itertuples(index=False,name=None))+'\n'

def analyze(cfg):
 frame=pd.read_csv(allowed(OUT/'path_comparisons/IR_NINE_CHECKPOINT_FIVE_PATH_STATISTICS.csv'),float_precision='round_trip');pair=pd.read_csv(allowed(OUT/'path_comparisons/IR_PATH_TO_PATH_COMPARISONS.csv'),float_precision='round_trip')
 exact={p:int(((frame.path_id==p)&(frame.status=='COMPARED')&(frame.array_equal==True)).sum()) for p in PATHS}
 match={key:int((g.array_equal==True).sum()) for key,g in pair.groupby('comparison')}
 primary='PHASE_IR_H_AUTHORITY_PARITY_VERIFIED' if exact['A']==9 else 'PHASE_IR_H_AUTHORITY_PARITY_NOT_REPRODUCED'
 labels=[]
 if exact['A']==9 and exact['E']<9:labels.append('PHASE_IR_I_EXECUTION_SEMANTICS_DIFFERENCE_OBSERVED')
 if all(exact[p]==0 for p in PATHS):labels.append('PHASE_IR_NUMERICAL_PARITY_UNRESOLVED')
 observations=[]
 for path_id,text in [('B','no_grad -> inference_mode alone'),('C','requires_grad=False alone'),('D','CPU construct/load -> CUDA alone')]:
  count=9-match.get(path_id+'-A',0);observations.append(f'{text}: {count}/9 outputs differ from Path A (exact comparison).')
 if exact['A']==9 and match.get('C-E')==9 and match.get('B-A')==9 and match.get('D-A')==9:
  cause='CONTROLLED_FACTOR_IDENTIFIED_REQUIRES_GRAD_FLAGS: disabling parameter gradient flags alone reproduces the full Path E numerical output in 9/9 checkpoints; no_grad/inference_mode alone and CPU-to-CUDA alone do not change outputs. This identifies an execution-context cause, not the unique internal CUDA/cuDNN kernel.'
 elif exact['A']==9 and match.get('B-E')==9 and match.get('C-A')==9 and match.get('D-A')==9:
  cause='CONTROLLED_FACTOR_IDENTIFIED_INFERENCE_MODE: inference_mode alone reproduces Path E in 9/9 checkpoints; the other single-variable paths do not change outputs. Unique internal kernel not identified.'
 else:
  cause='CONTROLLED_MATRIX_DEPENDENCE_DOCUMENTED; no unique single-factor attribution is assumed. Consult B-A, C-A, D-A and B/C/D-E comparisons before proposing any repair.'
 valid=frame.loc[(frame.status=='COMPARED')&(frame.finite==True)]
 e_rows=valid.loc[valid.path_id=='E'];h_rows=valid.loc[valid.path_id=='A']
 summary={'phase':PHASE.name,'base_commit':BASE,'primary_status':primary,'additional_statuses':labels,'path_exact_counts':exact,'path_to_path_exact_counts':match,'root_cause_evidence':cause,'observations':observations,'max_all_path_difference_mV':float(valid.max_abs_difference_mV.max()) if len(valid) else None,'max_Phase_I_PathE_difference_mV':float(e_rows.max_abs_difference_mV.max()) if len(e_rows) else None,'PathE_unequal_fraction_min':float(e_rows.unequal_fraction.min()) if len(e_rows) else None,'PathE_unequal_fraction_max':float(e_rows.unequal_fraction.max()) if len(e_rows) else None,'state_entries_changed':0 if valid.state_audit_pass.all() else None,'new_Assessment_protocol_technical_conditions':exact['A']==9 and len(h_rows)==9,'recommended_interface':'unmodified frozen H e.predict(model, fixed_preprocessed_inputs, 32, cuda); eval plus no_grad; preserve original requires_grad flags' if exact['A']==9 else 'No interface recommendation until original H authority is reproduced','new_protocol_required':True,'new_code_identity_required':True,'original_I_status':'PHASE_I_EXECUTION_BLOCKED','original_I_ledger_modified':False,'original_checkpoint_modified':False,'new_training':False,'new_Assessment_inference':False,'formal_Test_accessed':False,'protocol_sha256':digest(PROTOCOL),'code_identity_sha256':cfg['code_identity']['sha256'],'fixed_window_scope':'32 Validation origins x 24 steps, not full 205-origin Validation or Assessment','full_N1_hash':False,'automatic_Phase_I_restart':False}
 json_write(OUT/'IR_SUMMARY.json',summary)
 pivot=frame.pivot(index=['model','seed'],columns='path_id',values='array_equal').reset_index();maxima=frame.groupby(['model','seed']).max_abs_difference_mV.max().reset_index();pivot=pivot.merge(maxima,on=['model','seed'])
 csv_write(OUT/'path_comparisons/IR_PARITY_MATRIX.csv',pivot)
 identity=pd.DataFrame([{k:r[k] for k in ['H_run_id','model','seed','checkpoint_sha256','best_epoch','parameter_count','saved_prediction_sha256']} for r in cfg['checkpoints']])
 context=pd.DataFrame([{'path':p,**d} for p,d in cfg['paths'].items()])
 detailed=frame[['model','seed','path_id','status','array_equal','unequal_elements','unequal_fraction','max_abs_difference_standardized','mean_abs_difference_standardized','difference_RMSE_standardized','max_abs_difference_mV','difference_RMSE_mV','max_difference_sample_index_zero_based','max_difference_horizon_step','fixed32_actual_RMSE_mV','fixed32_saved_RMSE_mV','fixed32_RMSE_delta_mV']]
 common='\nOnly fixed 32 Validation origins are inferred. No Assessment, Test, training or model changes. Exact parity remains np.array_equal; diagnostic tolerances do not change the PASS rule.\n'
 report={
 'IR_H_VS_I_EXECUTION_COMPARISON.md':'# H versus I execution comparison\n'+common+'\n'+md(context)+'\nH creates on CUDA, strict-loads, and calls e.predict -> c.predict under no_grad with original gradient flags. I creates/loads on CPU, transfers to CUDA, disables flags and calls its unchanged predict_frozen under inference_mode. Each of the 45 paths runs in an independent Python child. No additional diagnostic forward calls are performed.\n\n'+md(identity)+'\nInput preprocessing uses the inherited C Validation builder and E EWMA/scaler-transform with persisted scaler, no fit. Full Validation input/label/origin/target-row hashes match H for all nine checkpoints. Only the first 32 are cached and predicted. I.load_protocol is deliberately not called because its broad source hashes include Assessment caches; I protocol/code/ledger identities are independently verified without reading those caches.\n',
 'IR_NINE_CHECKPOINT_PARITY.md':'# Nine-checkpoint five-path exact parity\n'+common+'\n'+md(pivot)+'\nPrimary status: `'+primary+'`.\n\n'+md(detailed)+'\nAll raw actual/saved/difference arrays, input/output/archive hashes, per-process logs and parameter/buffer entries are preserved. Exact=False is a retained numerical audit observation, not an exception or grounds to change tolerance.\n',
 'IR_NUMERICAL_DIFFERENCE_ANALYSIS.md':'# Numerical differences and independent audit\n'+common+'\n'+md(detailed)+'\n## Single-variable path comparisons\n\n'+md(pair)+'\n'+ '\n'.join('- '+s for s in observations)+'\n\nEvidence interpretation: '+cause+'\n\nAll difference statistics were persisted before judging parity. Scalar/math.fsum recalculation from saved NPZ archives agrees within 1e-12 for difference statistics and 1e-10 mV for optional fixed32 RMSE. NaN/Inf counts, maximum sample/horizon/origin and diagnostic tolerance fractions are included in the full CSV/JSON. The optional fixed32 RMSE does not update the historical 205-window Validation result. Small differences do not waive exact parity. No underlying kernel attribution, checkpoint-corruption claim or model-quality claim follows automatically.\n',
 'IR_FINAL_RECOMMENDATION.md':'# Phase I-R final recommendation\n'+common+'\n## Status\n\n`'+primary+'`\n\n'+', '.join(labels)+'\n\n'+md(pivot)+'\n## Cause and evidence level\n\n'+cause+'\n\n'+'\n'.join('- '+s for s in observations)+'\n\n## Unified interface and mathematical scope\n\n'+summary['recommended_interface']+'. This restores the frozen historical implementation rather than altering model equations, weights, input, hyperparameters, scaler or target. Numerical equivalence is demonstrated only for these fixed Validation inputs in the frozen environment, not every possible input or GPU.\n\n## Any future Assessment prerequisites\n\n1. Retain original Phase I protocol, BLOCKED ledger and reports unchanged.\n2. A separately authorized revised Assessment protocol is required; do not weaken the exact parity gate.\n3. Freeze a new execution-code identity using the demonstrated historical interface, and distinguish requires_grad flags from actual parameter updates.\n4. Reverify nine immutable checkpoints, environment, Development prefix and original Assessment keys/truth under the new authority.\n5. Reproduce all nine fixed Validation references exactly before any newly authorized Assessment forward.\n6. User authorization for that revised execution remains necessary; this audit does not unblock or restart I.\n\n## State and operation proof\n\nEvery successful path saves per-entry parameter/buffer hashes, equality, before/after gradient flags, grad=None, and operation guards. requires_grad=True is not training. No backward, optimizer creation, optimizer step or state change occurred on successful audited paths.\n\n## Limits and stop\n\nNew training NO; new Assessment inference NO; formal Test accessed NO; original I ledger modified NO; original checkpoints modified NO. Historical selection bias and E2/F0 reproducibility uncertainty are unchanged. Stop after the finite audit; no performance experiment, model selection, SOH/RUL or automatic I rerun.\n'}
 for name,body in report.items():
  path=PHASE/'reports'/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(body,encoding='utf-8',newline='\n')
 return summary

if __name__=='__main__':analyze(load_protocol())
